    tbc_t_full_ext = 0; tbc_p_full_ext = 0; tbc_t_empty_synch_rdclk = 0; tbc_p_empty_synch_rdclk = 0; tbc_t_req_l1 = 0; tbc_p_req_l1 = 0; tbc_t_req_l2 = 0; tbc_p_req_l2 = 0; tbc_t_req_l3 = 0; tbc_p_req_l3 = 0; tbc_t_req_l4 = 0; tbc_p_req_l4 = 0; tbc_t_req_c = 0; tbc_p_req_c = 0; tbc_t_data_out = 0; tbc_p_data_out = 0; tbc_t_tailer = 0; tbc_p_tailer = 0; tbc_t_tailer_org = 0; tbc_p_tailer_org = 0; tbc_t_data_sel = 0; tbc_p_data_sel = 0; tbc_t_header = 0; tbc_p_header = 0; tbc_t_empty = 0; tbc_p_empty = 0; tbc_t_fifo_out = 0; tbc_p_fifo_out = 0; tbc_t_header_flit = 0; tbc_p_header_flit = 0; tbc_t_mux_data_out = 0; tbc_p_mux_data_out = 0; tbc_t_header_out = 0; tbc_p_header_out = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 400 == 0);
      if (tb_rand(0) % 3 == 0) rd_en = ~rd_en;
      if (tb_rand(0) % 3 == 0) wr_en = ~wr_en;
      data_in = tb_flit(0);
      if (tb_cyc == 0) begin tb_r = tb_rand(0); current_address = {2'b00, 2'b01 + tb_r[4], 2'b00, 2'b01 + tb_r[0]}; end
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
module ip_chnl__ref (reset, rd_clk, wr_clk, rd_en, wr_en,  data_in, current_address, full_ext, empty_synch_rdclk, req_l1, req_l2, req_l3, req_l4, req_c, data_out, tailer, tailer_org, nxt_reset, data_sel, header, empty, fifo_out, header_flit, reg_out, mux_data_out, header_out);
	input reset, rd_clk, wr_clk, rd_en, wr_en ;
	 input [31:0] data_in ;
	 input [7:0] current_address ; 

	 output full_ext, empty_synch_rdclk ;
	 output req_l1, req_l2, req_l3, req_l4, req_c ;
    output [31:0] data_out ; 

	 output tailer ;
  
	 supply1 vdd ;
  	 output tailer_org, nxt_reset, data_sel ;
	 output header, empty ;
	 output [31:0] fifo_out, header_flit, reg_out, mux_data_out, header_out ; 
    
     reg [31:0] mux_data_out,header_out,data_out;
     reg clr1,header,tailer_org;
     wire rd_en_out; // added for Icarus: was implicit


always@(fifo_out,reset,rd_en_out,rd_en,rd_clk,wr_clk)
begin
 header = (!fifo_out[30]) & fifo_out[29];
 tailer_org=(fifo_out[30] & (!fifo_out[29]));	
end	 


	

always@(reset,header,tailer,header_flit,fifo_out,rd_clk,wr_clk)
		begin
		clr1= reset | tailer;


		if(header)
			header_out=fifo_out;
		else
			header_out=header_flit;
          
       end   

		





always@(data_sel,rd_en,header_flit,fifo_out,rd_clk )
	

begin
if(rd_en)
	begin	
		if(data_sel)
			mux_data_out=header_flit;
		else
			mux_data_out=fifo_out;
	end	
else
			mux_data_out=32'b01100000000000000000000000000000;
end


always@(mux_data_out)
begin
data_out = mux_data_out;
end




router_fifo  r1(.reset(reset), .rd_clk(rd_clk), .rd_en(rd_en_out), .data_in(data_in), 
   	.wr_clk(wr_clk), .wr_en(wr_en), .data_out(fifo_out), .full_int(full_ext), .empty(empty)) ;

register_32bit reg2(.dout(header_flit), .din(fifo_out), .clk(rd_clk), 
	                    .clr(clr1), .ce(header));
 
routing_algo_mesh mesh_logic(.header_in(header_out), .current_address(current_address), .reset(reset), .req_link1(req_l1), .req_link2(req_l2),.req_core(req_c),  .req_link3(req_l3),.req_link4(req_l4));
  
irs irs1 (.reset(reset), .empty(empty), .rd_en(rd_en), .rd_clk(rd_clk), .tailer_org(tailer_org), 
	.tailer(tailer), .rd_en_out(rd_en_out), .header(header), .data_sel(data_sel) );

dff_synch_reset dff_tailer (.d(tailer_org), .clk(rd_clk), .reset(reset), .q(tailer)) ;

dff_synch_set dff_empty(.d(empty), .clk(rd_clk), .set(reset), .q(empty_synch_rdclk)) ;

endmodule
